import java.util.Random;
import java.util.*;
/**
 * This class models weather in the simulation. 
 * It stores information about the current weather. 
 *
 * @version 2022.03.02
 */
public class Weather
{
    private WeatherType currentWeather;
    private static final Random rand = Randomizer.getRandom();
    private int randomInt;
    private int duration; // to keep track of when weather changes (every X hours)
    private boolean randomDuration = false;
    private Set<WeatherType> weatherList;


    /**
     * Create a new instance of weather. 
     */
    public Weather()
    {
       weatherList = new HashSet<>();
       addWeatherList();
       currentWeather = WeatherType.SUNNY; 
       duration = 0;
    }

    /**
     * Add the types of weather conditions to a HashSet.
     */
    public void addWeatherList()
    {
        weatherList = new HashSet<>(Arrays.asList(WeatherType.RAINING, WeatherType.SUNNY, WeatherType.CLOUDY));
    }

    /**
     * Returns the current weather of the simulation. 
     */
    public WeatherType getCurrentWeather()
    {
        return currentWeather;
    }

    /**
     * Increments the variable duration. 
     * If the duration is set to be random, the WeatherType lasts for 0-36 hours
     * Otherwise, the WeatherType lasts for 12 hours
     */
    public void checkWeatherChange(int steps)
    {
        if(randomDuration){
            duration = rand.nextInt(36);
            if(steps % duration==0){
                changeWeather();
            }
        }
        else{
            if (steps % 12 == 0){
                changeWeather();
            }
        }
    }

    /**
     * Allows for the duration of the weather to be switched from random (0-36 steps) to static (12 steps)
     * @return The new state of the randomDuration boolean
     */
    public boolean toggleRandomWeatherLength()
    {
        randomDuration = !randomDuration;
        return randomDuration;
    }

    /**
     * Changes the weather randomly. 
     */
    public void changeWeather()
    {
        randomInt = rand.nextInt(weatherList.size());
        currentWeather = (WeatherType) weatherList.toArray()[randomInt];
    }
}

/**
 * This class models time in the simulation. 
 * It stores details about time such as whether it is day or night,
 * the number of days the simulation has simulated through 
 * and the current time.
 *
 * @version 2022.03.2
*/
public class Time 
{
    // to keep track of the flow of time
    private int stepCount;
    private int dayCount;
    private TimesOfDay dayOrNight;


    /**
     * Create a new instance of time with the step set to 0.
     */
    public Time() 
    {
        stepCount = 0;
        dayOrNight = TimesOfDay.NIGHT;
    }

    /**
     * Increments the time by 1. 
     * Additionally increments the day counter if
     * 24 hours have passed. 
     * Calls the method checkDayOrNight()
     */
    public void incrementTime()
    {
        stepCount++;
        if(stepCount % 24 == 0){
            dayCount++;
        }
        checkDayOrNight();
    }

    /**
     * Checks the current hour and then sets 
     * time as day or night accordingly. 
     */
    public void checkDayOrNight()
    {
        if (getHour() >= 6 && getHour() <= 19) {
            dayOrNight = TimesOfDay.DAY;
        }
        else {
            dayOrNight  = TimesOfDay.NIGHT;
        }
    }

    /**
     * Returns the current hour of the simulation. 
     */
    private int getHour() 
    {
        return stepCount % 24; 
    }

    /**
     * Returns the current hour of the simulation 
     * as a string.
     */
    private String getHourString() 
    {
        int hour = getHour();
        if(hour < 10){
            return "0"+hour+":00";
        }
        return ""+hour+":00";
    }

    /**
     * Returns true if it is currently day time.
     */
    public boolean isDay() 
    {
        return dayOrNight==TimesOfDay.DAY;
    }

    /**
     * Returns the current time of the day.
     * Whether it is daytime or nighttime. 
     */
    public TimesOfDay getCurrentPeriod()
    {
        return dayOrNight;
    }

    /**
     * Returns the current time as a string.
     */
    public String getCurrentTimeString()
    {
        return " (" + getCurrentPeriod().toString() + ")" + " Day #" + dayCount + " " + getHourString();
    }

    /**
     * Returns the day count number. 
     */
    private int getDayCount()
    { 
        return dayCount; 
    }

    /**
     * Reset the time object
     */
    public void reset(){
        stepCount = 0;
        dayCount = 0;
        dayOrNight = TimesOfDay.NIGHT;
    }
}

