202	                    // If multiple instances of the simulation are created in the same session (for testing),
203	                    // the fields in SimulationInfo can be used for optimizing the default probabilities
204	                    SimulationInfo.HIGHEST_STEPS = backupCounter;
205	                    SimulationInfo.HIGHEST_STEP_PROBS = config.getPopulationRates();
206	                }
207	                playingSimulation = false;
208	                break;
209	            }
210	        }
211	        remainingSteps = numSteps - backupCounter;
212	    }
