214	    /**
215	     * Run the simulation from its current state for a single step.
216	     * Iterate over the whole field updating the state of each
217	     * organism.
218	     */
219	    public void simulateOneStep()
220	    {
221	        if(!playingSimulation){ return; }
222	        step++;
223	        environmentController.advance(step);
224	
225	
226	        // Provide space for newborn animals.
227	        List<Actor> newActors = new ArrayList<>();
228	        // Let all actors act.
229	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
230	            Actor actor = it.next();
231	            if(actor instanceof Animal){
232	               if(((Animal) actor).isAwake(environment)) {
233	                   if(((Animal) actor).isDiseased() && ((Animal) actor).getDisease().getPropagationRate() <= rand.nextDouble()) {
234	                       ((Animal) actor).setDead();
235	                   }
236	                   actor.act(newActors, environment);
237	               }
238	            }
239	            else {
240	                actor.act(newActors, environment);
241	            }
242	
243	            if(actor instanceof Plant){
244	                if(step % ((Plant) actor).STEPS_PER_STAGE()==0){
245	                    ((Plant) actor).incrementGrowth();
246	                }
247	            }
248	
249	            if(! actor.isAlive()) {
250	                it.remove();
251	            }
252	
253	
254	
255	        }
256	        actors.addAll(newActors);
257	        plantGrassInPatches();
258	
259	        view.showStatus(step, environmentController.getCurrentWeather().toString(), environmentController.getCurrentTimeString(), field);
260	    }
