262	    /**
263	     * Randomly generate grass in free patches on the field, only if it is raining
264	     */
265	    private void plantGrassInPatches(){
266	        // new grass is randomly added in patches
267	        double grassRate = config.getPopulationRate(Grass.class);
268	        for(Location location:field.getRandomFreePatches(grassRate)){
269	            if(rand.nextDouble() <= grassRate && environmentController.isRaining()) {
270	                Grass grass = new Grass(field, location);
271	                actors.add(grass);
272	            }
273	        }
274	    }
